      "summary": "10月21日IT之家消息，英伟达首席执行官黄仁勋在柏林GTC大会上提出，未来所有电信运营商都将提供AI算力，电信基站有望发展为分布式AI网络。他现场重提AI“五层蛋糕”理论，将人工智能从下至上划分为能源、芯片、基础设施、模型和应用五个层级，强调AI并非仅为软件，而是如同电力、互联网般的底层工业基础设施，各层级紧密相连、",
