      "title": "有序图案化面板光解水制氢研究取得进展",
      "summary": "首页 > 科研进展 基于半导体材料的光解水技术光生载流子易复合、表面逆反应严重，制约了制氢效率提升。全固态Z型异质结通过导电介质将两种半导体串联，既能提供高驱动力，又能把光生电子和空穴分别导向不同组分，因而备受关注。然而，传统颗粒型Z型体系多依赖颗粒间随机接触，电荷转移路径不可控，容易加剧复合，限制载流子利用效率。 近",
