      "angle": "Use researchers and facilities as reporting anchors, with the scientific mechanism, evidence and translational boundary, peer context and limitations clearly stated. For this item, test the claim behind “有序图案化面板光解水制氢研究取得进展” against primary-source evidence.",
      "status": "confirmed_today",
      "matchedTopic": "半导体供应链",
      "rawText": "首页 > 科研进展 基于半导体材料的光解水技术光生载流子易复合、表面逆反应严重，制约了制氢效率提升。全固态Z型异质结通过导电介质将两种半导体串联，既能提供高驱动力，又能把光生电子和空穴分别导向不同组分，因而备受关注。然而，传统颗粒型Z型体系多依赖颗粒间随机接触，电荷转移路径不可控，容易加剧复合，限制载流子利用效率。 近日，中国科学院金属研究所提出有序图案化策略，在FTO导电基底上构筑p型四方锆石BiVO 4 （t-BVO）与n型单斜白钨矿BiVO 4 （m-BVO）交替条纹，利用FTO介导Z-scheme电荷转移，实现光生电子和空穴的空间分离，有效抑制复合与逆反应，提升光催化全解水性能。 图案化集成过程以金属有机分解法在FTO上制备m-BVO薄膜，形成条纹图案。随后，在暴露的FTO区域用水热法外延生长t-BVO，最终获得约15μm宽的t-BVO/m-BVO交替条纹面板。结果表明，FTO作为导电介质在相邻条纹间建立了Z-scheme电荷转移通道，光生电子富集于p型t-BVO，光生空穴富集于n型m-BVO。基于此，团队将Rh@CrO x 选择性光沉积在t-BVO条纹上作为析氢助催化剂，将M",
