      "rawText": "2026可持续全球领导者大会10月20日-22日于上海召开，欧洲科学院院士、西湖大学可信及通用人工智能实验室创始人金耀初在演讲中指出，随着具备自主决策行动能力的AI智能体普及，AI安全与治理已成为核心议题，原有聚焦抑制大模型幻觉的早期治理逻辑需同步升级。他提出需从开发、使用两端发力搭建可控治理框架：开发之初明确划定AI智能体行为边界、做好权限隔离，研发者与普通使用者均恪守AI安全规范，双管齐下可整体管控AI安全风险。金耀初明确现阶段AI不具备自我意识，所谓越界行为本质是管控机制不完善导致的边界失效，强调需始终坚持AI对齐人类主流价值观，高风险重大判断的最终决定权必须牢牢掌握在人类手中。(AI生成)",
