      "rawText": "2026可持续全球领导者大会于10月20日-22日在上海召开，英国剑桥大学院士艾伦·麦克法兰提出可将AI视作陌生“部落”，用人类学参与式观察法研究。他将AI定位为人类文明第四大颠覆性变革，此前三次为语言诞生、文字发明、印刷术。他指出AI无主观生命体验，本质是复刻人类表达的镜子，人类真正的风险是自身活成机器，需善用AI工具，守住人独有的精神内核。(AI生成)",
